import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    output_lines = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            N = int(n_str)
        except StopIteration:
            break

        goals = []
        for _ in range(N):
            goals.append(int(next(iterator)))

        if N < 2:
            output_lines.append("UNFIT")
            continue

        min_so_far = goals[0]
        max_diff = -1

        for i in range(1, N):
            current_goals = goals[i]
            if current_goals > min_so_far:
                diff = current_goals - min_so_far
                if diff > max_diff:
                    max_diff = diff

            if current_goals < min_so_far:
                min_so_far = current_goals

        if max_diff > 0:
            output_lines.append(str(max_diff))
        else:
            output_lines.append("UNFIT")

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == "__main__":
    main()
